CREATE TABLE IF NOT EXISTS cms_sites(id BIGSERIAL PRIMARY KEY,site_key VARCHAR(190) NOT NULL UNIQUE,name TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN('active','staging','suspended','archived')),owner_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,agency_key VARCHAR(190) NOT NULL DEFAULT '',default_locale VARCHAR(10) NOT NULL DEFAULT 'en',settings_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_site_domains(id BIGSERIAL PRIMARY KEY,site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,domain VARCHAR(255) NOT NULL UNIQUE,is_primary BOOLEAN NOT NULL DEFAULT FALSE,verification_token VARCHAR(190) NOT NULL DEFAULT '',verified_at TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_cms_site_domains_site ON cms_site_domains(site_id,is_primary);
CREATE TABLE IF NOT EXISTS cms_site_memberships(site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,site_role VARCHAR(20) NOT NULL DEFAULT 'editor' CHECK(site_role IN('owner','admin','editor','author','support','viewer')),permissions_json TEXT NOT NULL DEFAULT '[]',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(site_id,user_id));
CREATE TABLE IF NOT EXISTS cms_site_settings(site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,setting_key VARCHAR(190) NOT NULL,setting_value TEXT NOT NULL DEFAULT '',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(site_id,setting_key));
CREATE TABLE IF NOT EXISTS cms_site_extensions(site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,extension_key VARCHAR(190) NOT NULL,is_enabled BOOLEAN NOT NULL DEFAULT TRUE,config_json TEXT NOT NULL DEFAULT '{}',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(site_id,extension_key));
CREATE TABLE IF NOT EXISTS cms_site_connectors(site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,connector_key VARCHAR(190) NOT NULL,connector_id BIGINT REFERENCES service_connectors(id) ON DELETE SET NULL,policy_json TEXT NOT NULL DEFAULT '{}',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(site_id,connector_key));
CREATE TABLE IF NOT EXISTS cms_site_clones(id BIGSERIAL PRIMARY KEY,source_site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,target_site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','completed','failed')),details_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TIMESTAMP);
INSERT INTO cms_sites(id,site_key,name,status,default_locale,settings_json) VALUES(1,'default','Default Site','active','en','{}') ON CONFLICT(id) DO NOTHING;
